class.main-text.0@span@p@html
<js>
a=java.getString('@css:[class="text-center grayout warning-tag"]@html',false);
b=java.getString('@css:[class="text-left grayout"]@html',false);
title=java.getString('@@class.text-center@tag.strong.1@class.h5@html',false);
r=java.getString('@@class.main-text!0@span@p@html',false);
if(a!=''){
a='◎作者有话说：'+a+'-END-'
}
if(b!=''){
b='◎作者有话说：\n'+b
}
if((!title.match(/<h5/))&&(title.match(/[\u4e00-\u9fa5]/))){
title='['+title+']'+'\n'
}else{title=''}
if(r!=''){
r='◎评论：\n'+r+'\n-完-'
}
result=title+a+result+b+r
</js>

