$.chaptername
@js:
result=result.replace(/^\s+/,'');
vip='{{$.isvip}}'!='0';
lock='{{$.islock}}'!='0';
type='{{$.chaptertype}}'=='1';
num=!type?'{{$.chapterid}}.':'';
